param([string]$DataDirectory=(Join-Path ([Environment]::GetFolderPath('Desktop')) 'Movira_test_Video/hands'),[string]$ManifestName='sources.json',[string]$Prefix='')
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies @("System.Drawing.Common","System.Drawing.Primitives","System.Private.Windows.GdiPlus","System.Private.Windows.Core","System.Runtime","System.Runtime.InteropServices") -TypeDefinition @'
using System;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;
public static class MoviraHandPixels { public static byte[] Crop(Bitmap source,float x,float y,float side){using(var output=new Bitmap(64,64,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(output)){g.Clear(Color.Black);g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBilinear;g.DrawImage(source,new RectangleF(0,0,64,64),new RectangleF(x,y,side,side),GraphicsUnit.Pixel);}var bits=output.LockBits(new Rectangle(0,0,64,64),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var bytes=new byte[64*64*4];for(int row=0;row<64;row++)Marshal.Copy(bits.Scan0+row*bits.Stride,bytes,row*256,256);return bytes;}finally{output.UnlockBits(bits);}}} }
'@
$root=[IO.Path]::GetFullPath($DataDirectory);$pixelName=$Prefix+'hands64.bgra';$sampleName=$Prefix+'hand-samples.json';$sources=Get-Content -LiteralPath (Join-Path $root $ManifestName) -Raw | ConvertFrom-Json -AsHashtable;$records=[Collections.Generic.List[object]]::new();$raw=[IO.File]::Create((Join-Path $root $pixelName));$subjects=@{}
foreach($r in $sources.records){if($subjects.ContainsKey($r.userId) -and $subjects[$r.userId] -ne $r.split){throw 'Subject overlap across source splits'};$subjects[$r.userId]=$r.split}
try{$imageIndex=0;foreach($r in $sources.records){$bitmap=[Drawing.Bitmap]::new((Join-Path $root $r.file));try{
for($hand=0;$hand -lt $r.points.Count;$hand++){$points=$r.points[$hand];if($null -eq $points -or $points.Count -ne 21 -or $hand -ge $r.boxes.Count){continue};$box=$r.boxes[$hand];if($box[2]*$bitmap.Width -lt 32 -or $box[3]*$bitmap.Height -lt 32){continue};$valid=$true;foreach($p in $points){if($p[0] -lt 0 -or $p[0] -gt 1 -or $p[1] -lt 0 -or $p[1] -gt 1){$valid=$false}};if(-not $valid){continue}
$left=[double]$box[0]*$bitmap.Width;$top=[double]$box[1]*$bitmap.Height;$right=$left+$box[2]*$bitmap.Width;$bottom=$top+$box[3]*$bitmap.Height;foreach($p in $points){$left=[Math]::Min($left,$p[0]*$bitmap.Width);$right=[Math]::Max($right,$p[0]*$bitmap.Width);$top=[Math]::Min($top,$p[1]*$bitmap.Height);$bottom=[Math]::Max($bottom,$p[1]*$bitmap.Height)};$side=[Math]::Max($right-$left,$bottom-$top)*1.3;$x=($left+$right-$side)/2;$y=($top+$bottom-$side)/2;$label=[Collections.Generic.List[double]]::new();foreach($p in $points){$label.Add(($p[0]*$bitmap.Width-$x)/$side);$label.Add(($p[1]*$bitmap.Height-$y)/$side)};$label.Add(1);$pixels=[MoviraHandPixels]::Crop($bitmap,$x,$y,$side);$raw.Write($pixels);$records.Add(@{id=$r.id+'-'+$hand;split=$r.split;userId=$r.userId;label=$label.ToArray();positive=$true;gesture=$r.gesture;sourceHand=$hand;roi=@{x=$x;y=$y;side=$side}})
}
if($imageIndex%3 -eq 0){$side=[Math]::Min($bitmap.Width,$bitmap.Height)*.18;foreach($location in @(@(0,0),@(($bitmap.Width-$side),0),@(0,($bitmap.Height-$side)),@(($bitmap.Width-$side),($bitmap.Height-$side)))){$x=[double]$location[0];$y=[double]$location[1];$overlap=$false;foreach($box in $r.boxes){if($x -lt ($box[0]+$box[2])*$bitmap.Width -and $x+$side -gt $box[0]*$bitmap.Width -and $y -lt ($box[1]+$box[3])*$bitmap.Height -and $y+$side -gt $box[1]*$bitmap.Height){$overlap=$true}};if(-not $overlap){$pixels=[MoviraHandPixels]::Crop($bitmap,$x,$y,$side);$raw.Write($pixels);$records.Add(@{id=$r.id+'-background';split=$r.split;userId=$r.userId;label=[double[]]::new(43);positive=$false;gesture='background';roi=@{x=$x;y=$y;side=$side}});break}}}
}finally{$bitmap.Dispose()};$imageIndex++;if($imageIndex%200 -eq 0){Write-Output "$imageIndex images, $($records.Count) hand/background crops"}}
}finally{$raw.Dispose()}
@{format='movira-hand-training-v1';width=64;height=64;channelOrder='BGRA';annotationMethod='HaGRIDv2 provider MediaPipe auto-labels; not human-verified joint truth';records=$records.ToArray()} | ConvertTo-Json -Depth 20 -Compress | Set-Content -LiteralPath (Join-Path $root $sampleName) -Encoding utf8
$preview=Join-Path $PSScriptRoot '../web/.dev';New-Item -ItemType Directory -Path $preview -Force | Out-Null
foreach($name in @($pixelName,$sampleName)){$target=Join-Path $preview $name;if(-not (Test-Path -LiteralPath $target)){New-Item -ItemType HardLink -Path $target -Target (Join-Path $root $name) | Out-Null}}
Write-Output "Prepared $($records.Count) crops in $root"
